import{I as p,o as t,c as r,b6 as e,J as o,w as d,j as i,a as l}from"./chunks/framework.BUXTSoD9.js";const u=JSON.parse('{"title":"ダブルダイヤモンドモデル：正しいことをして、正しくやる","description":"ゼロベースの読者向け Double Diamond 入門記事。Discover、Define、Develop、Deliver の4つの段階を理解し、問題が明確になる前にプロトタイプを作り始めるのを防ぐ。","frontmatter":{"title":"ダブルダイヤモンドモデル：正しいことをして、正しくやる","description":"ゼロベースの読者向け Double Diamond 入門記事。Discover、Define、Develop、Deliver の4つの段階を理解し、問題が明確になる前にプロトタイプを作り始めるのを防ぐ。"},"headers":[],"relativePath":"ja-jp/stage-1/appendix-double-diamond/index.md","filePath":"ja-jp/stage-1/appendix-double-diamond/index.md"}'),h={name:"ja-jp/stage-1/appendix-double-diamond/index.md"},k=Object.assign(h,{setup(c){const s="約 <strong>1.5 時間</strong>";return(g,a)=>{const n=p("ChapterIntroduction");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="ダブルダイヤモンドモデル-正しいことをして、正しくやる" tabindex="-1">ダブルダイヤモンドモデル：正しいことをして、正しくやる <a class="header-anchor" href="#ダブルダイヤモンドモデル-正しいことをして、正しくやる" aria-label="Permalink to “ダブルダイヤモンドモデル：正しいことをして、正しくやる”">​</a></h1><p><a id="top-dd"></a></p><h2 id="本章のガイド" tabindex="-1">本章のガイド <a class="header-anchor" href="#本章のガイド" aria-label="Permalink to “本章のガイド”">​</a></h2>',3)),o(n,{duration:s,tags:["Double Diamond","デザイン思考","要件分析","ソリューション設計"],coreOutput:"より明確な問題定義と、より合理的な検証の切り口",expectedOutput:"いきなりプロトタイプを作り始めるのではなく、まず問題を明確にしてからソリューションを比較できるようになる"},{default:d(()=>[...a[0]||(a[0]=[i("p",null,"多くの人が初めてプロダクトを作るとき、最も陥りやすい罠は「不够努力」ではなく、ソリューションに早く入りすぎることです。",-1),i("p",null,"頭の中に方向性が浮かんだ途端、ページのレイアウト、ボタンの配置、AIの統合の有無、ログイン登録の要否、プロトタイプのツール選びなどを考え始めます。色々と作業した後で、根本的な問題が全く考えられていなかったことに気づくのです：ユーザーに本当にそのペインポイントがあるのか？この問題に今取り組む価値があるのか？プロジェクトを前に進めているつもりで、実は間違った方向で一所懸命加速しているだけなのです。",-1),i("p",null,"ダブルダイヤモンドモデル（Double Diamond）は、まさにこの状況を防ぐためにあります。",-1),i("p",null,[l("このモデルが最も価値ある点は："),i("strong",null,"「正しいことをする」と「正しくやる」は、全く異なる2つの段階である"),l("という提醒です。問題がまだ明確になっていないのに、急いでプロトタイプを作り始めると、通常は間違った方向をより完全に仕上げるだけです。")],-1)])]),_:1}),a[2]||(a[2]=e(`<div class="info custom-block"><p class="custom-block-title">最小SOP</p><p><strong>目的</strong>：読み終えた後、プロダクトを作るときにいつまず問題を考え、いつからソリューションやプロトタイプを考え始めればよいかがより明確になり、いきなり間違った方向で一所懸命作業するのを防げるようになります。</p><p><strong>アクションアイテム</strong>：<code>Discover → Define → Develop → Deliver</code>の4つのステップに沿って進み、各ステップでその段階がやるべきことだけを行う。</p><p><strong>結果</strong>：より明確な問題定義、複数の比較可能なソリューション、そして検証可能な最小バージョンを得られます。</p><p><strong>キーワードジャンプ</strong>：<a href="#dd-what">ダブルダイヤモンドモデルとは</a> · <a href="#dd-first">最初のダイヤモンド</a> · <a href="#dd-ai">AIがどう役立つか</a></p></div><h2 id="以下の内容を学びます" tabindex="-1">以下の内容を学びます <a class="header-anchor" href="#以下の内容を学びます" aria-label="Permalink to “以下の内容を学びます”">​</a></h2><ol><li>ダブルダイヤモンドモデルとは何か、なぜゼロベースのプロダクト作りに適しているのか</li><li>Discover、Define、Develop、Deliver の4つの段階がそれぞれ何をしているのか</li><li>「今はまだ発散を続けるべき」か「今から収束を始めるべき」かをどう見分けるか</li><li>ダブルダイヤモンドモデルをAIプロダクト、プロトタイプ設計、要件検証にどう活用するか</li></ol><p><a id="dd-what"></a></p><h2 id="_1-ダブルダイヤモンドモデルとは" tabindex="-1"><a href="#top-dd">1. ダブルダイヤモンドモデルとは</a> <a class="header-anchor" href="#_1-ダブルダイヤモンドモデルとは" aria-label="Permalink to “1. ダブルダイヤモンドモデルとは”">​</a></h2><p>ダブルダイヤモンドモデルは、英国の<strong>Design Council</strong>が提唱した古典的なデザインプロセスフレームワークです。完全なデザイン・イノベーションプロセスを、2つの連続したダイヤモンド形で表します。</p><p>「ダイヤモンド」の形になっているのは、各ダイヤモンドが相反するがどちらも重要な2つのアクションを含んでいるからです：</p><ul><li><strong>発散</strong>：まず視野を広げ、より多くの可能性を見る</li><li><strong>収束</strong>：次に範囲を絞り、判断と取捨選択を行う</li></ul><p>全プロセスは4つのステップからなります：</p><ol><li><strong>Discover</strong>：ユーザー、問題、環境、市場を広く理解する</li><li><strong>Define</strong>：大量の情報から、本当に解決すべき核心問題を抽出する</li><li><strong>Develop</strong>：核心問題を中心に複数のソリューションを発散させる</li><li><strong>Deliver</strong>：スクリーニング、プロトタイプ、テスト、そしてより適切なソリューションを納品する</li></ol><p>この4つのステップを最も覚えやすい一言に圧縮すると：</p><ul><li><strong>最初のダイヤモンド</strong>：まず何を解決すべきかを明確にする</li><li><strong>2つ目のダイヤモンド</strong>：その問題をどう解決するかを決める</li></ul><p>これはあなたが正確に表現した次の言葉と同じです：</p><ul><li><strong>最初のダイヤモンド：正しいことをする</strong></li><li><strong>2つ目のダイヤモンド：正しくやる</strong></li></ul><h2 id="_2-なぜダブルダイヤモンドモデルは初心者に特に適しているのか" tabindex="-1">2. なぜダブルダイヤモンドモデルは初心者に特に適しているのか <a class="header-anchor" href="#_2-なぜダブルダイヤモンドモデルは初心者に特に適しているのか" aria-label="Permalink to “2. なぜダブルダイヤモンドモデルは初心者に特に適しているのか”">​</a></h2><p>初心者がプロダクトを作るとき、最もよくあるリズムは次のようになります：</p><ul><li>アイデアを思いつく</li><li>この方向性がかっこいいと思う</li><li>すぐにプロトタイプを作り始める</li><li>作っているうちに機能が増えていく</li><li>最終的に自分が何を解決しているのか分からなくなる</li></ul><p>ダブルダイヤモンドモデルの価値は、プロセスを複雑にすることではなく、<strong>「問題を理解する」と「ソリューションを設計する」を切り離す</strong>ことにあります。</p><p>これはシンプルに聞こえますが、実は非常に重要です。なぜなら、多くの失敗したプロダクトは、実行が不真面目だったのではなく：</p><ul><li>間違った問題を選んだ</li><li>ユーザーを誤解した</li><li>ソリューションを早すぎるとロックした</li><li>大量の時間を細部の磨き上げに費やし、方向性を検証しなかった</li></ul><p>ダブルダイヤモンドモデルは常に次のように提醒します：</p><ul><li>思いつきやすいからといって、問題が成立していると早とちりしない</li><li>ソリューションを作れるからといって、それが作る価値があるとは限らない</li><li>プロトタイプが完全に見えるからといって、ユーザーが本当に必要とするとは限らない</li></ul><p><a id="dd-first"></a></p><h2 id="_3-最初のダイヤモンド-正しいことをする" tabindex="-1"><a href="#top-dd">3. 最初のダイヤモンド：正しいことをする</a> <a class="header-anchor" href="#_3-最初のダイヤモンド-正しいことをする" aria-label="Permalink to “3. 最初のダイヤモンド：正しいことをする”">​</a></h2><p>最初のダイヤモンドが焦点を当てるのは<strong>問題そのもの</strong>であり、ソリューションではありません。</p><p>一言で理解するなら：<strong>まず急いで作るのではなく、本当にやる価値があるかどうかを明確にする。</strong></p><h3 id="_3-1-discover-まず問題空間を広げる" tabindex="-1">3.1 Discover：まず問題空間を広げる <a class="header-anchor" href="#_3-1-discover-まず問題空間を広げる" aria-label="Permalink to “3.1 Discover：まず問題空間を広げる”">​</a></h3><p>Discover段階の核心的なタスクは、<strong>広く調査することであり、早急に結論を出すことではありません。</strong></p><p>このステップで通常行うことには以下が含まれます：</p><ul><li>ユーザーが実際のシナリオでどう行動しているかを見る</li><li>潜在ユーザーにインタビューし、最後に問題に遭遇したのがいつかを理解する</li><li>現在どうやって代替手段で対処しているかを見る</li><li>競合や代替ソリューションの対応方法を確認する</li><li>市场、プロセス、制約、サプライチェーンの情報を収集する</li></ul><p>多くの人はDiscoverを「資料をたくさん見ること」と誤解しがちです。実はもっと重要なのは：<strong>情報とデータではなく、人とシナリオを理解することです。</strong></p><p>例えば「AIで議事録を整理するツール」を作りたい場合、Discover段階では以下に注目すべきです：</p><ul><li>ユーザーが会議後に最も苦痛に感じるのはどこか</li><li>議事録か、整理か、それとも共有か</li><li>現在は自分で書いているのか、インターンに頼んでいるのか、録音を聞き直しているのか、それとも整理していないのか</li><li>どの会議シナリオで議事録が最も必要で、どのシナリオでは不要なのか</li></ul><p>このステップの最も重要な目標は答えを出すことではなく、<strong>早すぎる段階で答えが分かったと思い込まないことです。</strong></p><h3 id="_3-2-define-大量の情報から核心問題を抽出する" tabindex="-1">3.2 Define：大量の情報から核心問題を抽出する <a class="header-anchor" href="#_3-2-define-大量の情報から核心問題を抽出する" aria-label="Permalink to “3.2 Define：大量の情報から核心問題を抽出する”">​</a></h3><p>Discoverが視野を広げることだとすれば、Defineは収束を始めることです。</p><p>Define段階でやるべきことは、すべての観察を残すことではなく、次の問いに答えることです：</p><ul><li>本当に最優先で解決すべき問題はどれか</li><li>どの問題が最も頻繁に発生し、最も痛みが強く、最も価値があるか</li><li>第1版ではどのシナリオに絞るべきか</li></ul><p>このステップの核心は、幅広いトピックを明確な問題定義に収束させることです。</p><p>例えば最初はこう言っていたかもしれません：</p><blockquote><p>会議の効率を高めるAIツールを作りたい。</p></blockquote><p>Define段階に到達すると、より良い表現は次のようになるかもしれません：</p><blockquote><p>プロジェクト型チームが30〜60分の協働会議を終えた後、10分以内にToDo、担当者、期限付きの議事録を出力できない問題を、まず解決する。</p></blockquote><p>ここで問題が明確になり始めます：</p><ul><li>ユーザーは誰か</li><li>シナリオは何か</li><li>ボトルネックは何か</li><li>成功基準は何か</li></ul><p>Defineの本質は、<strong>「問題がたくさんある」状態から「今回はどの問題を先に解決するか」への収束です。</strong></p><h2 id="_4-2つ目のダイヤモンド-正しくやる" tabindex="-1">4. 2つ目のダイヤモンド：正しくやる <a class="header-anchor" href="#_4-2つ目のダイヤモンド-正しくやる" aria-label="Permalink to “4. 2つ目のダイヤモンド：正しくやる”">​</a></h2><p>最初のダイヤモンドを完了して初めて、2つ目のダイヤモンドに進むのが適切です。なぜなら、この時点で解決しているのは曖昧な方向ではなく、収束された具体的な問題だからです。</p><h3 id="_4-1-develop-核心問題を中心にソリューションを発散させる" tabindex="-1">4.1 Develop：核心問題を中心にソリューションを発散させる <a class="header-anchor" href="#_4-1-develop-核心問題を中心にソリューションを発散させる" aria-label="Permalink to “4.1 Develop：核心問題を中心にソリューションを発散させる”">​</a></h3><p>Develop段階の重点は、<strong>同じ問題に対して、複数の可能なソリューションを探索することです。</strong></p><p>なお、ここの発散はDiscover段階のものとは異なります：</p><ul><li>Discoverの発散は、問題空間を探索すること</li><li>Developの発散は、ソリューション空間を探索すること</li></ul><p>議事録の例で言えば、Develop段階では以下のことを考え始めることができます：</p><ul><li>Webツールにするのか、会議プラグインにするのか</li><li>録音をアップロードしてから処理するのか、リアルタイムで記録するのか</li><li>要約だけにするのか、ToDo抽出をメインにするのか</li><li>個人効率を強調するのか、チーム共有を強調するのか</li><li>ユーザーに自由に編集させるのか、構造化テンプレートとして直接出力するのか</li></ul><p>このステップはブレインストーミングに適しており、チームと一緒にソリューションを広げるのにも適しています。</p><p>ただし、ここには一つの前提があります：<strong>すべてのソリューションは、定義済みの同じ問題にサービスする必要があります。</strong> 問題が明確に定義されていないと、Developは再び機能の乱れに戻ってしまいます。</p><h3 id="_4-2-deliver-ソリューションの選択、プロトタイプ、テスト、納品" tabindex="-1">4.2 Deliver：ソリューションの選択、プロトタイプ、テスト、納品 <a class="header-anchor" href="#_4-2-deliver-ソリューションの選択、プロトタイプ、テスト、納品" aria-label="Permalink to “4.2 Deliver：ソリューションの選択、プロトタイプ、テスト、納品”">​</a></h3><p>Deliver段階は2つ目のダイヤモンドの収束段階です。</p><p>このときやるべきことは、さらに多くのアイデアを考えることではなく、判断を始めることです：</p><ul><li>現在の段階に最も適したソリューションはどれか</li><li>最小で最も有用なバージョンはどれか</li><li>どの機能を先に作る必要があり、どれは後回しでいいか</li><li>プロトタイプ、テスト、小規模検証をどう進めるか</li></ul><p>多くの人はDeliver＝「公開」と誤解しがちです。実際のより正確な意味は：<strong>ソリューションをテスト可能、検証可能、反復可能なものに変えることです。</strong></p><p>それは次のようなものかもしれません：</p><ul><li>低 fidelity のフロー図</li><li>Figma プロトタイプ</li><li>動作するMVP</li><li>小規模なユーザーテスト</li><li>実際のフィードバック後の反復バージョン</li></ul><p>Deliverのポイントは「完璧な納品」ではなく、<strong>できるだけ早くソリューションを実際の環境で検証することです。</strong></p><h2 id="_5-最も覚えやすい比較表" tabindex="-1">5. 最も覚えやすい比較表 <a class="header-anchor" href="#_5-最も覚えやすい比較表" aria-label="Permalink to “5. 最も覚えやすい比較表”">​</a></h2><p>4つの段階がいつも混同されるなら、以下のバージョンを直接覚えてください：</p><table tabindex="0"><thead><tr><th>段階</th><th>何をしているか</th><th>キーワード</th><th>一般的な成果物</th></tr></thead><tbody><tr><td>Discover</td><td>問題を理解する</td><td>調査、観察、インタビュー、情報収集</td><td>ユーザーインサイト、シナリオノート、問題リスト</td></tr><tr><td>Define</td><td>問題を定義する</td><td>抽出、焦点、取捨選択、問題の書き直し</td><td>問題定義、優先順位、MVPの切り口</td></tr><tr><td>Develop</td><td>ソリューションを探索する</td><td>ブレインストーミング、比較、共創、プロトタイプの構想</td><td>ソリューションリスト、フローのラフスケッチ、プロトタイプの方向性</td></tr><tr><td>Deliver</td><td>ソリューションを検証する</td><td>プロトタイプ、テスト、反復、納品</td><td>プロトタイプ、テストフィードバック、最適化バージョン</td></tr></tbody></table><p>さらに圧縮すると：</p><ul><li><strong>Discover / Define</strong>：「正しいことをする」を解決する</li><li><strong>Develop / Deliver</strong>：「正しくやる」を解決する</li></ul><h2 id="_6-ダブルダイヤモンドモデルの最もよくある誤解" tabindex="-1">6. ダブルダイヤモンドモデルの最もよくある誤解 <a class="header-anchor" href="#_6-ダブルダイヤモンドモデルの最もよくある誤解" aria-label="Permalink to “6. ダブルダイヤモンドモデルの最もよくある誤解”">​</a></h2><h3 id="_6-1-discover前にいきなりdeliver" tabindex="-1">6.1 Discover前にいきなりDeliver <a class="header-anchor" href="#_6-1-discover前にいきなりdeliver" aria-label="Permalink to “6.1 Discover前にいきなりDeliver”">​</a></h3><p>これが最もよくあるパターンです。アイデアを思いついた瞬間にプロトタイプを書き始め、PRDを書き、モデルを統合し、ページを作る。</p><p>問題は真面目にやっていないのではなく、問題が解決する価値があるかどうかをまだ確認していない可能性があることです。</p><h3 id="_6-2-discoverを長くやりすぎて、defineに入らない" tabindex="-1">6.2 Discoverを長くやりすぎて、Defineに入らない <a class="header-anchor" href="#_6-2-discoverを長くやりすぎて、defineに入らない" aria-label="Permalink to “6.2 Discoverを長くやりすぎて、Defineに入らない”">​</a></h3><p>もう一つの極端な例は、ずっと調査し、ずっと資料を見続け、ずっとインタビューしているのに、収束するのを恐れることです。</p><p>ダブルダイヤモンドは無限の発散を促すものではなく、発散の後には必ず判断と取捨選択に入る必要があることを提醒します。</p><h3 id="_6-3-defineの後、こっそり問題を変える" tabindex="-1">6.3 Defineの後、こっそり問題を変える <a class="header-anchor" href="#_6-3-defineの後、こっそり問題を変える" aria-label="Permalink to “6.3 Defineの後、こっそり問題を変える”">​</a></h3><p>多くのチームはDevelop段階で、あるソリューションが作りやすいからといって、逆に問題定義を変更して既存のソリューションに適合させようとします。</p><p>これは非常に危険です。なぜなら、問題を解決しているのではなく、自分の好きなソリューションに理由を見つけているだけかもしれないからです。</p><h3 id="_6-4-deliverを「すべて盛りで公開」と誤解する" tabindex="-1">6.4 Deliverを「すべて盛りで公開」と誤解する <a class="header-anchor" href="#_6-4-deliverを「すべて盛りで公開」と誤解する" aria-label="Permalink to “6.4 Deliverを「すべて盛りで公開」と誤解する”">​</a></h3><p>Deliverは完全なプロダクトをすべて作り終えて初めて終わりという意味ではありません。多くの場合、テスト可能なプロトタイプ、1回の実際のユーザートライアルが、すでに良いdeliverです。</p><h2 id="_7-aiプロダクトで、ダブルダイヤモンドモデルをどう使うか" tabindex="-1">7. AIプロダクトで、ダブルダイヤモンドモデルをどう使うか <a class="header-anchor" href="#_7-aiプロダクトで、ダブルダイヤモンドモデルをどう使うか" aria-label="Permalink to “7. AIプロダクトで、ダブルダイヤモンドモデルをどう使うか”">​</a></h2><p>AIプロダクトは特に「能力先行」の罠に陥りやすいです。なぜならモデルの能力があまりにも魅力的に見えるからです。以下のことを考え始めたくなります：</p><ul><li>マルチモーダルを統合するかどうか</li><li>Agentにするかどうか</li><li>ワークフローを追加するかどうか</li><li>音声、画像、インターネット検索を統合するかどうか</li></ul><p>しかし、ダブルダイヤモンドモデルはまず以下の問いを強制します：</p><ul><li>ユーザーはどのステップで本当に詰まっているのか</li><li>このボトルネックは本当にAIでなければ解決できないのか</li><li>AIを使わない場合、既存の方法はどこが最も悪いのか</li><li>AIを加えた後、最も核心的な進展は何か</li></ul><p>これはよくある状況を回避するのに役立ちます：<strong>能力は強いが、価値は弱い。</strong></p><p>実用的な順序は次の通りです：</p><ol><li>Discover段階でユーザーが現在タスクをどう処理しているかを観察する</li><li>Define段階で最も痛みの強いシナリオを一文の明確な問題定義にする</li><li>Develop段階でどのAI能力がこの問題に最も適しているかを比較する</li><li>Deliver段階で最小バージョンを作り、実際のユーザーにテストしてもらう</li></ol><h2 id="_8-そのまま使えるダブルダイヤモンドテンプレート" tabindex="-1">8. そのまま使えるダブルダイヤモンドテンプレート <a class="header-anchor" href="#_8-そのまま使えるダブルダイヤモンドテンプレート" aria-label="Permalink to “8. そのまま使えるダブルダイヤモンドテンプレート”">​</a></h2><p>自分のプロダクトを作っている場合は、まずこの順序に従って書いてみてください：</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>観察したユーザーは誰ですか？</li><li>そのユーザーが最後にこの問題に遭遇したのはいつですか？</li><li>現在どうやって解決していますか？</li><li>最も煩わしい、最も遅い、最も不安な部分はどこですか？</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>この山積みの問題の中で、最も優先して解決すべきものはどれですか？</li><li>どのシナリオが最も頻度が高い、または最も重要ですか？</li><li>第1版ではまず誰にサービスし、何だけを解決しますか？</li><li>問題が解決された後、ユーザーの状態はどう変わりますか？</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>この問題に対して、どのような可能なソリューションがありますか？</li><li>どのソリューションが最も軽く、最も速く、最も検証しやすいですか？</li><li>何を必ずやる必要があり、何は後回しにできますか？</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>この方向を検証するために、最小で何を納品できますか？</li><li>フロー図、プロトタイプ、それともMVPですか？</li><li>誰にテストを依頼しますか？</li><li>テスト後、継続、修正、中止をどう判断しますか？</li></ul><h2 id="_9-ゼロベースでも理解できる例" tabindex="-1">9. ゼロベースでも理解できる例 <a class="header-anchor" href="#_9-ゼロベースでも理解できる例" aria-label="Permalink to “9. ゼロベースでも理解できる例”">​</a></h2><p>「大学生の就職活動用レジュメ作成を支援する」AIツールを作りたいと仮定します。</p><p>多くの人は最初から2つ目のダイヤモンドに入り、次のことを考え始めます：</p><ul><li>ワンクリックで美しくするかどうか</li><li>AIで書き直すかどうか</li><li>JDと自動マッチングするかどうか</li><li>自己紹介を生成するかどうか</li></ul><p>しかし、ダブルダイヤモンドモデルに従えば、より良いプロセスは次のようになります：</p><h3 id="最初のダイヤモンド" tabindex="-1">最初のダイヤモンド <a class="header-anchor" href="#最初のダイヤモンド" aria-label="Permalink to “最初のダイヤモンド”">​</a></h3><p><strong>Discover</strong></p><ul><li>新卒学生が最後にレジュメを修正したのがいつかを聞きに行く</li><li>古いレジュメをどうやって新しいバージョンに変えたかを見る</li><li>最も苦痛なのが「書き方が分からない」「修正の仕方が分からない」なのか、「良し悪しの判断ができない」なのかを理解する</li></ul><p><strong>Define</strong></p><ul><li>最終的により具体的な問題に収束する：</li><li>「大学生がレジュメを作れない」ではなく</li><li>「初めてインターンに応募する学生が、既存の経験をポジションに合った表現に書き直せず、応募を先延ばしにしている」</li></ul><h3 id="_2つ目のダイヤモンド" tabindex="-1">2つ目のダイヤモンド <a class="header-anchor" href="#_2つ目のダイヤモンド" aria-label="Permalink to “2つ目のダイヤモンド”">​</a></h3><p><strong>Develop</strong></p><ul><li>いくつかのソリューションを考える：テンプレートライブラリ、AI書き直し、ポジション比較、レジュメスコアリング、ケース参考</li></ul><p><strong>Deliver</strong></p><ul><li>第1版は「ポジション記述に基づいて経験のbullet pointsを書き直す」機能のみ</li><li>5人の学生に試用してもらい、最初の版のレジュメをより早く提出できるかどうかを確認する</li></ul><p>最初のダイヤモンドをしっかりやれば、2つ目のダイヤモンドはずっと明確になることが分かるでしょう。</p><h2 id="_10-まとめ" tabindex="-1">10. まとめ <a class="header-anchor" href="#_10-まとめ" aria-label="Permalink to “10. まとめ”">​</a></h2><p>ダブルダイヤモンドモデルが最も力を発揮するのは、全体のごちゃ混ぜ状態を4つのより明確なアクションに分解することです：</p><ul><li>まず発散して問題を理解する</li><li>その後収束して問題を定義する</li><li>再び発散してソリューションを探索する</li><li>最後に収束してソリューションを納品する</li></ul><p>これはあなたを遅くするのではなく、<strong>忙しく見えて実は方向が間違っている遠回りを大幅に減らしてくれます。</strong></p><p>特にAI時代において、ものを作るスピードがますます速くなる中、ダブルダイヤモンドモデルは逆に重要になります。なぜなら「作る」ことがますます簡単になると、本当に希少な能力は次のようになるからです：<strong>あなたが解決する価値のある問題を解決しているか、そして適切な方法でそれを解決しているかどうか。</strong></p><p>この一言を覚えておけば十分です：</p><p><strong>まず正しいことをして、その後正しくやる。</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-aiを使ってダブルダイヤモンドプロセスを進める方法" tabindex="-1"><a href="#top-dd">11. AIを使ってダブルダイヤモンドプロセスを進める方法</a> <a class="header-anchor" href="#_11-aiを使ってダブルダイヤモンドプロセスを進める方法" aria-label="Permalink to “11. AIを使ってダブルダイヤモンドプロセスを進める方法”">​</a></h2><p>ダブルダイヤモンドモデル自体はAIツールではありませんが、AIは4つの段階で「アクセラレーター」として非常に適しています。重要なのは、AIに意思決定を任せるのではなく、視野の拡大、情報の整理、ソリューションの比較、検証資料の生成を支援させることです。</p><h3 id="_11-1-discover段階で、aiを使ってまず情報の基盤を作る" tabindex="-1">11.1 Discover段階で、AIを使ってまず情報の基盤を作る <a class="header-anchor" href="#_11-1-discover段階で、aiを使ってまず情報の基盤を作る" aria-label="Permalink to “11.1 Discover段階で、AIを使ってまず情報の基盤を作る”">​</a></h3><p>正式なインタビューや調査の前に、AIに軽量な問題スキャンをさせると良いでしょう：</p><ul><li>市場にある一般的な代替ソリューションは何か</li><li>ユーザーが公開コミュニティで最もよく不満を言っているのは何か</li><li>この問題はどのようなシナリオとユーザー層に多いか</li><li>既存のプロダクトが通常見落としているのは何か</li></ul><p>このステップは実際の調査に代わるものではありませんが、問題マップを素早く構築するのに非常に適しています。</p><p>シンプルな初心者入力は次のようなものです：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>大学生のレジュメ添削を支援するツールを作りたい。</span></span>
<span class="line"><span>まず機能を考える前に、この問題で皆が最もよく遭遇するトラブルを見てほしい。</span></span></code></pre></div><p>AIは次のような出力をするかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>初期問題マップ：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. どんな経験を書けばいいか分からない</span></span>
<span class="line"><span>2. ポジションに合わせてどう修正すればいいか分からない</span></span>
<span class="line"><span>3. 何度修正しても十分良いかどうか確信が持てない</span></span>
<span class="line"><span>4. 誰かに見てもらいたいが、毎回頼むのは気が引ける</span></span>
<span class="line"><span>5. 確信がないため、提出を先延ばしにしてしまう</span></span></code></pre></div><p>この出力の目的は、あなたに代わって結論を出すことではなく、Discoverにより早く入るためのものです。</p><h3 id="_11-2-define段階で、aiに問題定義の収束を支援させる" tabindex="-1">11.2 Define段階で、AIに問題定義の収束を支援させる <a class="header-anchor" href="#_11-2-define段階で、aiに問題定義の収束を支援させる" aria-label="Permalink to “11.2 Define段階で、AIに問題定義の収束を支援させる”">​</a></h3><p>多くの人は資料をたくさん集めた後、問題を本当に明確な一文に圧縮するのが最も難しいと感じます。調査ノートをAIに渡して、複数の候補問題定義に圧縮してもらうことができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>以下はDiscover段階で収集したユーザーフィードバックと調査ノートです：</span></span>
<span class="line"><span>[内容を貼り付ける]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>次の3つのことをしてください：</span></span>
<span class="line"><span>1. 最も頻繁に出現する問題パターンを分類・整理する</span></span>
<span class="line"><span>2. 問題の頻度、痛みの強さ、検証可能性に基づいて、優先的に解決すべき3つの問題を整理する</span></span>
<span class="line"><span>3. 各問題を具体的な問題定義の一文に書く</span></span></code></pre></div><p>これにより、Defineによりスムーズに入れるようになります。「問題がたくさんある」状態に留まり続けることがなくなります。</p><p>入力を非常にシンプルに書くこともできます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>現在収集した問題は以下の通りです：</span></span>
<span class="line"><span>1. 皆はレジュメに何を書けばいいか分からない</span></span>
<span class="line"><span>2. 皆はどう修正すればいいか分からない</span></span>
<span class="line"><span>3. 皆はいつもまだ十分に修正できていないと感じ、提出をためらう</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第1版ではどの問題を先に解決するのが最も適切か見てほしい。</span></span></code></pre></div><p>AIは次のような出力をするかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>優先的に解決すべき問題：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「初めてインターンに応募する学生が、レジュメが提出可能なレベルに達しているか確信が持てず、何度も修正を繰り返して提出を先延ばしにしている。」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>理由：</span></span>
<span class="line"><span>1. この問題はより具体的である</span></span>
<span class="line"><span>2. 先延ばし行動を説明できる</span></span>
<span class="line"><span>3. 小さなバージョンで検証しやすい</span></span></code></pre></div><p>このような出力は非常に有用です。なぜなら、曖昧な問題の山からMVPの出発点により近い定義へと収束させてくれるからです。</p><h3 id="_11-3-develop段階で、aiに複数のソリューションを発散させる" tabindex="-1">11.3 Develop段階で、AIに複数のソリューションを発散させる <a class="header-anchor" href="#_11-3-develop段階で、aiに複数のソリューションを発散させる" aria-label="Permalink to “11.3 Develop段階で、AIに複数のソリューションを発散させる”">​</a></h3><p>問題を定義した直後、頭に浮かんだ最初のソリューションだけに固執しがちです。AIはこのステップで強制的に発散させるのに非常に適しています：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>私はすでに核心問題を定義しました：[あなたの問題定義]</span></span>
<span class="line"><span>最終的な回答を直接出すのではなく、以下の角度からそれぞれ2〜3種類の解決方向を提案してください：</span></span>
<span class="line"><span>1. 最も軽量なMVP</span></span>
<span class="line"><span>2. ニーズ検証に最も適したソリューション</span></span>
<span class="line"><span>3. 体験向上に最も適したソリューション</span></span>
<span class="line"><span>4. AIに依存しないソリューション</span></span>
<span class="line"><span>5. AIに依存するソリューション</span></span>
<span class="line"><span>最後に各ソリューションのメリット、リスク、検証コストを比較してください。</span></span></code></pre></div><p>これにより、一つのソリューションに早すぎる段階で縛られなくなります。</p><p>シンプルな入力は次のように書けます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>私の現在の問題定義は：</span></span>
<span class="line"><span>「大学生はレジュメが提出可能かどうか確信が持てず、ずっと先延ばしにしている。」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4つの異なるソリューションを考えてほしい、1つだけでいいのにしないでほしい。</span></span></code></pre></div><p>AIは次のような出力をするかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ソリューション1：レジュメ提出チェックリスト</span></span>
<span class="line"><span>ソリューション2：ポジション記述に基づく针对性のある書き直し</span></span>
<span class="line"><span>ソリューション3：ユーザーがレジュメをアップロードした後にリスク警告を提示</span></span>
<span class="line"><span>ソリューション4：優秀なケースとの照合を提供し、ユーザーがギャップを判断できるようにする</span></span></code></pre></div><p>これにより、「ソリューションの比較」に入りやすくなり、最初からAI書き直しという一つの方向だけに固執しなくなります。</p><h3 id="_11-4-deliver段階で、aiにプロトタイプのテキストとテスト資料の生成を支援させる" tabindex="-1">11.4 Deliver段階で、AIにプロトタイプのテキストとテスト資料の生成を支援させる <a class="header-anchor" href="#_11-4-deliver段階で、aiにプロトタイプのテキストとテスト資料の生成を支援させる" aria-label="Permalink to “11.4 Deliver段階で、AIにプロトタイプのテキストとテスト資料の生成を支援させる”">​</a></h3><p>Deliver段階に入ると、AIは次の作業を加速するのに非常に適しています：</p><ul><li>低 fidelity プロトタイプのページテキストの生成</li><li>ユーザーテストスクリプトの整理</li><li>比較可能な複数バージョンのタイトル、ボタン、説明文の生成</li><li>テスト後のフィードバックと問題リストの整理</li></ul><p>例えば、AIに20分間のユーザーテストスクリプトを生成させたり、5人のユーザーフィードバックを「継続／方向修正／一時停止」の判断基準に整理させたりすることができます。</p><p>例えば、最もシンプルな入力は次のように書けます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>非常にシンプルなプロトタイプを作った：</span></span>
<span class="line"><span>ユーザーがレジュメをアップロードすると、システムがどこがまだ提出に適していないかを教える。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15分間のユーザーテストスクリプトを生成してほしい。</span></span></code></pre></div><p>AIは次のような出力をするかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15分間テストスクリプト：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. まずユーザーに最近のレジュメ提出経験を説明してもらう</span></span>
<span class="line"><span>2. ユーザーに自力でレジュメのアップロードを完了してもらう</span></span>
<span class="line"><span>3. フィードバック結果を理解できるか観察する</span></span>
<span class="line"><span>4. 質問する：これらのヒントのうち、どれが最も役立ち、どれが混乱を招いたか</span></span>
<span class="line"><span>5. 質問する：次回提出前に、もう一度使いたいと思うか</span></span></code></pre></div><p>このような出力は非常に実用的です。なぜなら、「プロトタイプが完成した」から「次にどうテストするか」まで導いてくれるからです。</p><h3 id="_11-5-aiに「段階ゲートキーパー」を演じさせる" tabindex="-1">11.5 AIに「段階ゲートキーパー」を演じさせる <a class="header-anchor" href="#_11-5-aiに「段階ゲートキーパー」を演じさせる" aria-label="Permalink to “11.5 AIに「段階ゲートキーパー」を演じさせる”">​</a></h3><p>ダブルダイヤモンドモデルで最もよくある問題は、ステップを飛ばすことです。AIに直接ゲートキーパーを務めさせ、今がどのステップにいるのかをリマインドさせることができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>あなたはプロダクトプロセスコーチとして行動してください。</span></span>
<span class="line"><span>以下は私の現在のプロジェクトの状態です：[あなたの説明]</span></span>
<span class="line"><span>私が現在Discover、Define、Develop、Deliverのどれにいるかを判断してください。</span></span>
<span class="line"><span>そして以下を教えてください：</span></span>
<span class="line"><span>1. 早すぎる次の段階へのジャンプをしていないか</span></span>
<span class="line"><span>2. 現在の段階で最も補うべきアクションは何か</span></span>
<span class="line"><span>3. 今はまだやるべきでないことは何か</span></span></code></pre></div><p>これは初心者にとって特に役立ちます。なぜなら、「問題がまだ明確になっていないのにプロトタイプを作り始める」ことが非常に起こりやすいからです。</p><h2 id="📚-課題" tabindex="-1">📚 課題 <a class="header-anchor" href="#📚-課題" aria-label="Permalink to “📚 課題”">​</a></h2><p>上記の内容に基づいて、次の課題を完了してください：</p><ol><li>最近作りたいプロダクトのアイデアを1つ選び、Discover、Define、Develop、Deliverの4ステップのドラフトを書く</li><li>Define段階で、問題を強制的に一文に圧縮する</li><li>Develop段階で、少なくとも3種類の異なるソリューションをリストアップし、最初に思いついた方法だけに固執しない</li><li>Deliver段階で、1週間以内に納品可能な最小検証バージョンを書き出す</li></ol><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to “参考文献”">​</a></h2><p>この記事は主にDesign CouncilのDouble Diamondに関する公式資料を参照しており、さらに深く読むのに適しています：</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{u as __pageData,k as default};
